-- Lugares reais de São Paulo (pesquisa de 25/11/2026). Endereço e fonte por lugar; coordenadas via OpenStreetMap/Nominatim.
-- Reexecutável: atualiza pelo id.
on conflict (id) do update set name = excluded.name, kind = excluded.kind, category_id = excluded.category_id,
  neighborhood = excluded.neighborhood, address = excluded.address, latitude = excluded.latitude, longitude = excluded.longitude,
  geo_precision = excluded.geo_precision, source_url = excluded.source_url, checked_at = excluded.checked_at, is_active = true;
